/**
 * Lab research multiplier helper — shared by UW duration, stun scaling, chrono, etc.
 *
 * ## Pipeline
 *
 *   if labUsesIncreaseCurve:
 *     mult = researchBaseBenefit[lab] × researchBenefitIncrease[lab]
 *   else:
 *     mult = researchBaseBenefit[lab]   // level-only curve
 *
 *   if lab locked / no array entry:
 *     mult = 1.0
 *
 * Used by: Poison Swamp duration/stun, Chrono Field, Thunder Bot linger, and other UW labs.
 */

export interface LabResearchTable {
  /** Per-lab base benefit at level 0 (or flat base). */
  baseBenefit: readonly number[]
  /** Per-lab per-level increase when curve uses multiply mode. */
  benefitIncrease?: readonly number[]
  /** When true, mult = base × increase; when false, mult = base only. */
  usesIncreaseCurve?: readonly boolean[]
}

export interface LabMultInput {
  labIndex: number
  /** Current selected lab level (0 if locked). */
  labLevel: number
  tables: LabResearchTable
}

/** Swamp / UW lab catalog indices (tracker slug → index). */
export const UW_LAB_INDICES = {
  chronoFieldDuration: 53,
  chronoFieldDamageReduction: 54,
  chronoFieldReduction: 55,
  swampRadius: 56,
  swampStun: 57,
  swampStunChance: 58,
  swampStunTime: 59,
  chronoFieldRange: 69,
  innerMineStun: 93,
  flameBotBurnStack: 106,
  thunderBotLingerTime: 107,
  swampRendBasicEnemies: 156,
  swampRendAdditionalEnemies: 157,
} as const

export function getLabResearchMult(input: LabMultInput): number {
  const { labIndex, labLevel, tables } = input
  if (labLevel <= 0) return 1

  const base = tables.baseBenefit[labIndex]
  if (base == null || !Number.isFinite(base)) return 1

  const usesIncrease = tables.usesIncreaseCurve?.[labIndex] ?? true
  if (!usesIncrease) return base

  const increase = tables.benefitIncrease?.[labIndex] ?? 1
  return base * increase
}

/**
 * Swamp duration CC rating scaler.
 *
 *   ccRating = max(1.0, controller.ccRating)
 *   durationBase = floor(ccRating) × getLabResearchMult(swampDurationLab) + 1
 *   scaled = inputMult × durationBase
 */
export function scaleSwampDuration(
  ccRating: number,
  labMult: number,
  inputMult: number,
): number {
  const cc = Math.max(1, ccRating)
  const durationBase = Math.floor(cc) * labMult + 1
  return inputMult * durationBase
}
